{"cards": [{"node_code": "N_66af932ad342d3b5", "definition": "研究物质组分在静止或流动介质中传递的基础理论，涵盖分子扩散、对流传质机理及边界层内的传质规律。", "boundary": "聚焦于传质过程的物理机制与数学描述，包括菲克定律、对流扩散方程、传质边界层厚度及传质系数关联式。与“热质传递类比”的区别在于：本节点侧重传质本身的动力学与边界层结构，而非热质类比关系；与“塔设备”的区别在于：本节点关注微观/介观传递机理，而非宏观设备设计。", "includes": ["分子扩散、对流传质及边界层理论", "传质系数、施密特数等无量纲数关联式", "气液、液液及气固界面上的传质机理"], "excludes": ["基于热质类比推导的换热计算（归入热质传递类比与湿空气过程）", "精馏塔、吸收塔等具体分离设备的结构设计（归入塔设备、精馏与膜分离过程）"], "sibling_distinctions": [{"other_code": "N_1dec5a67844bff0a", "rule": "本节点关注传质基础理论与边界层；兄弟节点关注热质类比方法及应用。"}, {"other_code": "N_168b4d6484420087", "rule": "本节点关注传质机理；兄弟节点关注利用传质原理的宏观分离设备。"}], "cross_boundary_rule": ""}, {"node_code": "N_1dec5a67844bff0a", "definition": "研究热量传递与质量传递之间的类比关系，以及湿空气中水蒸气与干空气混合过程中的热质耦合特性。", "boundary": "聚焦于利用热质类比（如刘易斯数、Chilton-Colburn类比）简化计算，以及湿空气性质（焓、含湿量、露点）在空调、干燥等工程中的应用。与“扩散、对流传质”的区别在于：本节点侧重类比方法及应用场景（如湿空气），而非基础传质机理；与“蒸发、干燥”的区别在于：本节点侧重湿空气状态及类比计算，而非相变过程本身。", "includes": ["热质传递类比理论及刘易斯数应用", "湿空气性质、焓湿图及空调负荷计算", "涉及水蒸气传递的热质耦合工程分析"], "excludes": ["不涉及水蒸气或组分变化的纯热量传递（归入导热、对流换热）", "干燥设备的具体结构设计及相变动力学细节（归入蒸发、干燥与相变传质过程）"], "sibling_distinctions": [{"other_code": "N_66af932ad342d3b5", "rule": "本节点关注类比方法及湿空气应用；兄弟节点关注基础传质理论与边界层。"}, {"other_code": "N_a91df3976e6f34bb", "rule": "本节点关注湿空气性质及类比；兄弟节点关注蒸发、干燥等相变过程机理。"}], "cross_boundary_rule": ""}, {"node_code": "N_c553bea58bc06807", "definition": "研究用于热量或热量与物质同时传递的设备设计，涵盖各类换热器、蒸发器及提高传递效率的强化技术。", "boundary": "聚焦于换热/传质设备的结构形式、性能分析及强化手段。包括间壁式、紧凑式、蓄热式换热器，以及涉及相变的蒸发器。与“塔设备”的区别在于：本节点侧重热交换或相变设备，而非以组分分离为主要目的的塔器；与“扩散、对流传质”的区别在于：本节点侧重工程设备设计，而非基础理论。", "includes": ["间壁式、紧凑式、微通道及蓄热式换热器设计", "直接接触式换热器及蒸发器", "传热/传质强化技术（如翅片、表面改性、湍流促进）"], "excludes": ["以组分分离为主要目的的塔设备（归入塔设备、精馏与膜分离过程）", "不涉及相变或组分变化的纯流体运动分析（归入流体力学）"], "sibling_distinctions": [{"other_code": "N_168b4d6484420087", "rule": "本节点侧重换热/蒸发设备；兄弟节点侧重精馏、吸收等分离塔器。"}, {"other_code": "N_a91df3976e6f34bb", "rule": "本节点侧重设备结构与强化；兄弟节点侧重蒸发、干燥过程机理。"}], "cross_boundary_rule": "涉及蒸发设备时，若侧重设备结构、换热面积计算及强化，主挂载至本节点；若侧重蒸发动力学、干燥曲线及相变机理，主挂载至“蒸发、干燥与相变传质过程”。"}]}
